def merge_intervals(intervals):
    if not intervals:
        return []

    sorted_intervals = sorted(intervals, key=lambda x: x[0])
    merged = []

    for start, end in sorted_intervals:
        if not merged:
            merged.append([start, end])
        else:
            last_start, last_end = merged[-1]
            if start <= last_end:
                merged[-1][1] = max(last_end, end)
            else:
                merged.append([start, end])

    return merged

import heapq


def toposort(nodes, edges):
    # Deduplicate edges so duplicate edges don't affect in-degree counts
    unique_edges = set(edges)

    # Build in-degree and adjacency structures without mutating inputs
    indeg = {n: 0 for n in nodes}
    adj = {n: [] for n in nodes}

    for u, v in unique_edges:
        adj[u].append(v)
        indeg[v] += 1

    # Min-heap to always pick the lexicographically smallest available node
    heap = [n for n in nodes if indeg[n] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(heap, v)

    if len(result) != len(nodes):
        raise ValueError("Graph contains a cycle")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError
    batches = []
    current_batch = []
    current_weight = 0
    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError
        if current_weight + weight <= limit:
            current_batch.append(name)
            current_weight += weight
        else:
            batches.append(current_batch)
            current_batch = [name]
            current_weight = weight
    if current_batch:
        batches.append(current_batch)
    return batches

import re


def parse_env(text: str) -> dict:
    env = {}
    key_re = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")

    for line in text.splitlines():
        stripped = line.strip()
        # skip blank lines and comment lines
        if not stripped or stripped.startswith("#"):
            continue

        eq_pos = stripped.find("=")
        if eq_pos == -1:
            raise ValueError(f"Invalid env line (no '='): {line!r}")

        key = stripped[:eq_pos].strip()
        value = stripped[eq_pos + 1:].strip()

        # validate key format
        if not key_re.fullmatch(key):
            raise ValueError(f"Invalid key: {key!r}")

        # strip matching quotes that enclose the whole value
        if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
            value = value[1:-1]

        env[key] = value

    return env

