    current_data_lines = []

    for line in lines:
        if line == '':
            # Blank line dispatches the current event
            if current_data_lines:
                data_str = '\n'.join(current_data_lines)
                if data_str == '[DONE]':
                    return events          # stop, exclude [DONE] and later
                events.append(data_str)
            current_data_lines = []
            continue

        if line.startswith('data:'):
            value = line[5:]             # everything after "data:"
            if value.startswith(' '):
                value = value[1:]        # remove at most one space after colon
            current_data_lines.append(value)
            continue

        # Ignore comments and other SSE fields
        if line.startswith(':'):
            continue
        if line.startswith('event:') or line.startswith('id:') or line.startswith('retry:'):
            continue

        # Any other field is ignored

    # unterminated final event is silently dropped
    return events

