def fifo_admit(active, queued, budget, slots):
    if any(r > budget for r in queued):
        raise ValueError("Queued reservation exceeds budget")

    i = 0
    n = len(queued)
    active_slots = len(active)
    active_tokens = sum(active)

    while i < n:
        head = queued[i]
        if active_slots + 1 <= slots and active_tokens + head <= budget:
            active_slots += 1
            active_tokens += head
            i += 1
        else:
            break

    return queued[:i], queued[i:]
